# LogiVisir deja de manejar productos con precio y montos de los pedidos:
# solo optimiza el reparto. Antes de borrar los productos, lo que llevaba cada
# pedido se copia a la nueva nota en texto ("4 x Marraqueta (kg)"), sin
# precios, para no perder el detalle de los despachos ya registrados.

from django.db import migrations, models


def copiar_items_a_nota(apps, schema_editor):
    Pedido = apps.get_model("core", "Pedido")
    for pedido in Pedido.objects.prefetch_related("items__producto"):
        partes = [f"{item.cantidad} x {item.producto.nombre}" for item in pedido.items.all()]
        if partes:
            pedido.nota = ", ".join(partes)[:500]
            pedido.save(update_fields=["nota"])


